parameters.inputSchema:
={
  "type": "object",
  "properties": {
    "lead_id": {
      "type": "string",
      "description": "Generate or pass Lead ID, format e.g. L-0001"
    },
    "client_name": {
      "type": "string",
      "description": "Client's name extracted from input"
    },
    "email": {
      "type": "string",
      "description": "Client's email address extracted from input"
    },
    "subject": {
      "type": "string",
      "description": "Email subject line"
    },
    "email_body": {
      "type": "string",
      "description": "Full follow-up email body"
    },
    "followup_type": {
      "type": "string",
      "description": "Type of follow-up (e.g. Scheduling Meeting / Meeting Confirmation)"
    },
    "intent": {
      "type": "string",
      "description": "Primary client intent"
    },
    "priority": {
      "type": "string",
      "enum": ["High", "Medium", "Low"]
    },
    "email_status": {
      "type": "string",
      "description": "Set default as 'Sent' or 'Pending'"
    },
    "followup_count": {
      "type": "integer",
      "description": "Increment follow-up count (e.g. 1)"
    },
    "next_action": {
      "type": "string",
      "description": "Recommended next action"
    }
  },
  "required": [
    "lead_id",
    "client_name",
    "email",
    "subject",
    "email_body",
    "followup_type",
    "intent",
    "priority",
    "email_status",
    "followup_count",
    "next_action"
  ]
}
